import type { Glossary, GlossaryEntry } from "./glossary";

/**
 * Every short form and term the System Design series leans on, with a one-line meaning, an
 * everyday example and the lesson that explains it. Hovering (or tapping) any of these inside
 * a /system-design lesson shows the entry in place; the full list is at /system-design/glossary.
 *
 * Acronyms (TLS, CDN, SLO …) are marked everywhere they appear. Ordinary words and product
 * names (latency, Kafka …) carry `once` and are marked only on their first use per page.
 */
const ENTRIES: GlossaryEntry[] = [
  // ── Networking & the Internet ─────────────────────────────────────────
  { term: "IP", full: "Internet Protocol", desc: "Gives every device an address and moves packets between networks. Example: Like a house address on an envelope: 142.250.183.14.", lesson: 1, group: "Networking & the Internet" },
  { term: "IPv4 / IPv6", aliases: ["IPv4", "IPv6"], full: "IP version 4 / 6", desc: "Two address formats. IPv4 is short (and has run out); IPv6 is long, with almost unlimited addresses. Example: IPv4: 192.168.1.10; IPv6: 2001:db8::1.", lesson: 1, group: "Networking & the Internet" },
  { term: "CIDR", full: "Classless Inter-Domain Routing", desc: "A short way to write a range of IP addresses. Example: 10.0.0.0/16 means all addresses from 10.0.0.0 to 10.0.255.255.", lesson: 1, group: "Networking & the Internet" },
  { term: "NAT", full: "Network Address Translation", desc: "Lets many private devices share one public IP. Example: Your home Wi-Fi router: all phones and laptops appear online as one address.", lesson: 1, group: "Networking & the Internet" },
  { term: "DNS", full: "Domain Name System", desc: "Turns human names into IP addresses. Example: The internet's phone book: amazon.com → 52.94.236.248.", lesson: 1, group: "Networking & the Internet" },
  { term: "TTL", full: "Time To Live", desc: "How long something may be cached or kept before it expires. Example: A DNS answer with TTL 300 can be reused for 5 minutes.", lesson: 1, group: "Networking & the Internet" },
  { term: "TCP", full: "Transmission Control Protocol", desc: "Reliable, ordered delivery of data. Resends anything lost. Example: A courier with tracking: every page arrives, in order. Used by websites and databases.", lesson: 2, group: "Networking & the Internet" },
  { term: "UDP", full: "User Datagram Protocol", desc: "Fast delivery with no guarantees. Lost data isn't resent. Example: Shouting across a room: fast, but some words may be missed. Used by video calls and games.", lesson: 2, group: "Networking & the Internet" },
  { term: "QUIC", full: "originally \"Quick UDP Internet Connections\"", desc: "A modern protocol built on UDP, with reliability and encryption built in. Example: Powers HTTP/3. Pages load faster on patchy mobile networks.", lesson: 2, group: "Networking & the Internet" },
  { term: "RTT", full: "Round-Trip Time", desc: "Time for a message to go to a server and back. Example: India → US and back ≈ 200+ ms.", lesson: 1, group: "Networking & the Internet" },
  { term: "MTU", full: "Maximum Transmission Unit", desc: "The largest packet size a network link can carry. Example: Usually about 1,500 bytes on Ethernet. Bigger data is split into several packets.", lesson: 1, group: "Networking & the Internet" },
  { term: "BGP", full: "Border Gateway Protocol", desc: "How large networks tell each other which IP addresses they can reach. Example: The internet's map. Facebook's 2021 outage happened when its BGP routes disappeared.", lesson: 1, group: "Networking & the Internet" },
  { term: "ISP", full: "Internet Service Provider", desc: "The company that connects you to the internet. Example: Your broadband or mobile data provider.", lesson: 1, group: "Networking & the Internet" },
  { term: "LAN / WAN", aliases: ["LAN", "WAN"], full: "Local / Wide Area Network", desc: "A LAN is a small network (home, office); a WAN connects distant locations. Example: Office Wi-Fi is a LAN; the link between two office cities is a WAN.", group: "Networking & the Internet" },
  { term: "VPN", full: "Virtual Private Network", desc: "An encrypted tunnel into a private network over the internet. Example: Working from home but accessing office systems securely.", group: "Networking & the Internet" },
  { term: "OSI model", aliases: ["OSI"], full: "Open Systems Interconnection", desc: "A 7-layer model describing how network communication works. Example: \"L4\" and \"L7\" load balancers come from this model.", lesson: 1, group: "Networking & the Internet" },
  { term: "L4 / L7", aliases: ["L4", "L7"], full: "Layer 4 / Layer 7", desc: "L4 = transport (IP + port). L7 = application (HTTP: URLs, headers). Example: An L4 load balancer sees \"port 443\"; an L7 one sees \"GET /api/orders\".", lesson: 12, group: "Networking & the Internet" },
  { term: "Port", aliases: ["port", "ports", "Ports"], full: "Port", desc: "A number that identifies a program on a machine. Example: 80 = HTTP, 443 = HTTPS, 22 = SSH, 5432 = PostgreSQL.", lesson: 1, group: "Networking & the Internet", once: true },
  { term: "Socket", aliases: ["socket", "sockets", "Sockets"], full: "Socket", desc: "One end of a network connection: IP + port + protocol. Example: Your browser tab talking to 142.250.183.14:443.", lesson: 1, group: "Networking & the Internet", once: true },
  { term: "Anycast", aliases: ["anycast", "anycasts", "Anycasts"], full: "Anycast", desc: "The same IP address is announced from many locations; users reach the nearest one. Example: Cloudflare's 1.1.1.1 is answered by a nearby data centre wherever you are.", lesson: 11, group: "Networking & the Internet", once: true },
  { term: "GeoDNS", full: "Geographic DNS", desc: "DNS returns different IPs based on where the user is. Example: Users in India get the Mumbai servers; users in Germany get Frankfurt.", lesson: 11, group: "Networking & the Internet" },
  { term: "PoP", full: "Point of Presence", desc: "A CDN or network location in a city. Example: A CDN with PoPs in Chennai, Delhi and Mumbai.", lesson: 14, group: "Networking & the Internet" },
  { term: "Egress / Ingress", aliases: ["Egress", "egress", "Ingress", "ingress"], full: "Egress / Ingress", desc: "Data going out of / into a network or cloud. Example: Cloud providers usually charge for egress (data sent to users).", lesson: 10, group: "Networking & the Internet", once: true },

  // ── Web, HTTP & APIs ──────────────────────────────────────────────────
  { term: "HTTP", full: "HyperText Transfer Protocol", desc: "The request/response language of the web. Example: Browser: GET /products/991 → server: 200 OK + data.", lesson: 3, group: "Web, HTTP & APIs" },
  { term: "HTTPS", full: "HTTP Secure", desc: "HTTP encrypted with TLS. Example: The padlock in your browser's address bar.", lesson: 3, group: "Web, HTTP & APIs" },
  { term: "HTTP/1.1, HTTP/2, HTTP/3", aliases: ["HTTP", "1.1"], full: "HTTP/1.1, HTTP/2, HTTP/3", desc: "HTTP versions: one request at a time per connection → many at once (multiplexing) → over QUIC. Example: HTTP/2 loads all of a page's images over one connection.", lesson: 3, group: "Web, HTTP & APIs" },
  { term: "URL / URI", aliases: ["URL", "URI"], full: "Uniform Resource Locator / Identifier", desc: "The address of a resource on the web. Example: https://shop.com/products/991?color=blue.", lesson: 1, group: "Web, HTTP & APIs" },
  { term: "Status codes", aliases: ["status codes"], full: "Status codes", desc: "Three-digit results of an HTTP request. Example: 200 OK, 201 Created, 404 Not Found, 429 Too Many Requests, 503 Unavailable.", lesson: 3, group: "Web, HTTP & APIs", once: true },
  { term: "CORS", full: "Cross-Origin Resource Sharing", desc: "Lets a server allow web pages from other domains to call it. Example: Your React app on app.com calling api.com.", lesson: 3, group: "Web, HTTP & APIs" },
  { term: "HSTS", full: "HTTP Strict Transport Security", desc: "Tells browsers to always use HTTPS for a site. Example: Even if you type http://bank.com, the browser goes to https://.", lesson: 3, group: "Web, HTTP & APIs" },
  { term: "API", full: "Application Programming Interface", desc: "A defined way for programs to talk to each other. Example: A weather app asks a weather API: \"What's the temperature in Pune?\".", lesson: 30, group: "Web, HTTP & APIs" },
  { term: "REST", full: "Representational State Transfer", desc: "An API style built on resources (nouns) and HTTP methods (verbs). Example: GET /users/42, POST /orders, DELETE /orders/7.", lesson: 30, group: "Web, HTTP & APIs" },
  { term: "CRUD", full: "Create, Read, Update, Delete", desc: "The four basic operations on data. Example: POST, GET, PUT/PATCH, DELETE in REST.", lesson: 30, group: "Web, HTTP & APIs" },
  { term: "JSON", full: "JavaScript Object Notation", desc: "A simple text format for data. Example: {\"name\": \"Asha\", \"age\": 28}.", lesson: 30, group: "Web, HTTP & APIs" },
  { term: "RPC", full: "Remote Procedure Call", desc: "Calling a function on another machine as if it were local. Example: inventory.CheckStock(\"991\") runs on another server.", lesson: 31, group: "Web, HTTP & APIs" },
  { term: "gRPC", full: "(Google's) RPC framework", desc: "Fast, typed RPC over HTTP/2 using Protocol Buffers. Example: Internal service-to-service calls in microservices.", lesson: 31, group: "Web, HTTP & APIs" },
  { term: "Protobuf", aliases: ["protobuf", "protobufs", "Protobufs"], full: "Protocol Buffers", desc: "A compact binary data format with a schema. Example: The same data as JSON, but much smaller and faster to parse.", lesson: 31, group: "Web, HTTP & APIs", once: true },
  { term: "GraphQL", full: "Graph Query Language", desc: "Lets clients ask for exactly the fields they need in one request. Example: A mobile app fetches name + last 3 orders + thumbnails in one call.", lesson: 32, group: "Web, HTTP & APIs" },
  { term: "OpenAPI", full: "formerly Swagger", desc: "A standard file describing a REST API. Example: Generates docs and client SDKs automatically.", lesson: 30, group: "Web, HTTP & APIs" },
  { term: "SDK", full: "Software Development Kit", desc: "A library that makes an API easy to use in a language. Example: Stripe's Python SDK for taking payments.", group: "Web, HTTP & APIs" },
  { term: "BFF", full: "Backend For Frontend", desc: "A small API layer tailored to one type of client. Example: A mobile BFF returns compact data; a web BFF returns detailed data.", lesson: 13, group: "Web, HTTP & APIs" },
  { term: "WebSocket", full: "WebSocket", desc: "A persistent, two-way connection between browser and server. Example: Chat messages arriving instantly.", lesson: 33, group: "Web, HTTP & APIs" },
  { term: "SSE", full: "Server-Sent Events", desc: "A one-way stream of updates from server to browser over HTTP. Example: AI answers appearing word by word; live scores.", lesson: 33, group: "Web, HTTP & APIs" },
  { term: "WebRTC", full: "Web Real-Time Communication", desc: "Peer-to-peer audio, video and data in browsers. Example: Video calls in the browser.", lesson: 33, group: "Web, HTTP & APIs" },
  { term: "MQTT", full: "Message Queuing Telemetry Transport", desc: "A lightweight publish/subscribe protocol for devices. Example: Smart home sensors sending temperature readings.", lesson: 33, group: "Web, HTTP & APIs" },
  { term: "Webhook", aliases: ["webhook", "webhooks", "Webhooks"], full: "Webhook", desc: "A server calls your URL when something happens. Example: Payment provider calls /webhooks/payment when a payment succeeds.", lesson: 34, group: "Web, HTTP & APIs", once: true },
  { term: "Idempotency", aliases: ["idempotency", "idempotencys", "Idempotencys"], full: "Idempotency", desc: "Doing something twice has the same effect as doing it once. Example: A lift button: pressing it 5 times still calls one lift. Retrying a payment with the same key charges once.", lesson: 34, group: "Web, HTTP & APIs", once: true },
  { term: "Pagination / Cursor", aliases: ["Pagination", "pagination", "paginations", "Paginations", "Cursor", "cursor", "cursors", "Cursors"], full: "Pagination / Cursor", desc: "Returning results a page at a time; a cursor is a bookmark to the next page. Example: \"Load more\" on a feed.", lesson: 34, group: "Web, HTTP & APIs", once: true },
  { term: "ETag", full: "Entity Tag", desc: "A fingerprint of a resource's version. Example: \"Has this changed since version abc123?\" If not → 304 Not Modified.", lesson: 3, group: "Web, HTTP & APIs" },
  { term: "Rate limit", aliases: ["rate limit"], full: "Rate limit", desc: "A cap on how many requests a client can make in a time window. Example: \"100 requests per minute on the Free plan\".", lesson: 43, group: "Web, HTTP & APIs", once: true },

  // ── Operating Systems & Concurrency ───────────────────────────────────
  { term: "CPU", full: "Central Processing Unit", desc: "Runs program instructions. Example: More cores = more work in parallel.", lesson: 4, group: "Operating Systems & Concurrency" },
  { term: "RAM", full: "Random Access Memory", desc: "Fast, temporary working memory. Example: Redis keeps its data in RAM, which is why it's fast.", lesson: 10, group: "Operating Systems & Concurrency" },
  { term: "SSD / HDD", aliases: ["SSD", "HDD"], full: "Solid State Drive / Hard Disk Drive", desc: "Permanent storage. SSD has no moving parts and is much faster. Example: Databases run far better on SSDs.", lesson: 10, group: "Operating Systems & Concurrency" },
  { term: "I/O", aliases: ["is", "Is", "os", "Os"], full: "Input/Output", desc: "Reading/writing disks, network, files. Example: Waiting for a database reply is I/O.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Process", aliases: ["process"], full: "Process", desc: "A running program with its own memory. Example: Each Chrome tab is roughly its own process.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Thread", aliases: ["thread", "threads", "Threads"], full: "Thread", desc: "A worker inside a process that shares its memory. Example: A web server handling 200 requests with 200 threads.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Concurrency / Parallelism", aliases: ["Concurrency", "concurrency", "concurrencys", "Concurrencys", "Parallelism", "parallelism", "parallelisms", "Parallelisms"], full: "Concurrency / Parallelism", desc: "Juggling many tasks / doing many tasks at the same instant. Example: One cook switching dishes vs several cooks at once.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Event loop", aliases: ["event loop"], full: "Event loop", desc: "One thread handling many tasks by never waiting idly. Example: Node.js and NGINX serving thousands of connections.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Race condition", aliases: ["race condition"], full: "Race condition", desc: "A bug where the result depends on the timing of concurrent actions. Example: Two people booking the last seat at the same moment.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Mutex / Lock", aliases: ["Mutex", "mutex", "mutexs", "Mutexs", "Lock", "lock", "locks", "Locks"], full: "Mutual exclusion", desc: "Lets only one thread use something at a time. Example: A single key to the storeroom.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "Deadlock", aliases: ["deadlock", "deadlocks", "Deadlocks"], full: "Deadlock", desc: "Two tasks each wait for the other forever. Example: Two cars blocking each other on a narrow bridge.", lesson: 4, group: "Operating Systems & Concurrency", once: true },
  { term: "GIL", full: "Global Interpreter Lock", desc: "Lets only one thread run Python code at a time (in standard CPython). Example: Python uses multiple processes for CPU-heavy work.", lesson: 4, group: "Operating Systems & Concurrency" },
  { term: "Connection pool", aliases: ["connection pool"], full: "Connection pool", desc: "A reusable set of open connections. Example: 20 database connections shared by all requests.", lesson: 5, group: "Operating Systems & Concurrency", once: true },
  { term: "C10K", full: "10,000 concurrent connections", desc: "The classic challenge of handling many simultaneous connections. Example: Solved by event loops and non-blocking I/O.", lesson: 4, group: "Operating Systems & Concurrency" },

  // ── Performance, Capacity & Reliability Numbers ───────────────────────
  { term: "Latency", aliases: ["latency", "latencys", "Latencys"], full: "Latency", desc: "Time to complete one request. Example: \"The API responds in 80 ms.\".", lesson: 8, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "Throughput", aliases: ["throughput", "throughputs", "Throughputs"], full: "Throughput", desc: "Work done per unit of time. Example: \"The API handles 5,000 requests per second.\".", lesson: 8, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "Bandwidth", aliases: ["bandwidth", "bandwidths", "Bandwidths"], full: "Bandwidth", desc: "Maximum data capacity of a link. Example: A 1 Gbps network connection.", lesson: 8, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "QPS / RPS / TPS", aliases: ["QPS", "RPS", "TPS"], full: "Queries / Requests / Transactions Per Second", desc: "Measures of load. Example: \"Peak 15,000 QPS on the feed.\".", lesson: 10, group: "Performance, Capacity & Reliability Numbers" },
  { term: "p50 / p95 / p99", aliases: ["p50", "p95", "p99"], full: "50th / 95th / 99th percentile", desc: "The latency that 50% / 95% / 99% of requests are faster than. Example: p99 = 800 ms means 1 in 100 requests takes longer than 800 ms.", lesson: 8, group: "Performance, Capacity & Reliability Numbers" },
  { term: "DAU / MAU", aliases: ["DAU", "MAU"], full: "Daily / Monthly Active Users", desc: "Number of users active per day / month. Example: \"10M DAU\" is the starting point of most estimates.", lesson: 10, group: "Performance, Capacity & Reliability Numbers" },
  { term: "Little's Law", full: "Little's Law", desc: "Items in the system = arrival rate × time each spends. Example: 500 req/s × 0.04 s = 20 requests in flight.", lesson: 8, group: "Performance, Capacity & Reliability Numbers" },
  { term: "Availability / \"nines\"", aliases: ["Availability", "availability", "availabilitys", "Availabilitys", "nines", "Nines"], full: "Availability / \"nines\"", desc: "% of time (or requests) the system works. Example: 99.9% ≈ 8.8 hours of downtime per year.", lesson: 9, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "SLI", full: "Service Level Indicator", desc: "What you measure about user experience. Example: % of checkout requests that succeed.", lesson: 47, group: "Performance, Capacity & Reliability Numbers" },
  { term: "SLO", full: "Service Level Objective", desc: "Your target for an SLI. Example: 99.9% of checkouts succeed over 28 days.", lesson: 47, group: "Performance, Capacity & Reliability Numbers" },
  { term: "SLA", full: "Service Level Agreement", desc: "A promise to customers with penalties. Example: \"Below 99.9% monthly uptime, you get a 10% credit.\".", lesson: 47, group: "Performance, Capacity & Reliability Numbers" },
  { term: "Error budget", aliases: ["error budget"], full: "Error budget", desc: "Allowed failure = 100% − SLO. Example: 99.9% SLO on 10M requests → 10,000 failures allowed.", lesson: 47, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "Burn rate", aliases: ["burn rate"], full: "Burn rate", desc: "How fast you're using the error budget. Example: Burn rate 14.4 = whole monthly budget gone in ~2 days.", lesson: 47, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "MTBF", full: "Mean Time Between Failures", desc: "Average time between failures. Example: Failing once a month = MTBF ≈ 720 hours.", lesson: 9, group: "Performance, Capacity & Reliability Numbers" },
  { term: "MTTR", full: "Mean Time To Recovery (or Repair)", desc: "Average time to recover from a failure. Example: Rollback in 5 minutes instead of 4 hours.", lesson: 9, group: "Performance, Capacity & Reliability Numbers" },
  { term: "RPO", full: "Recovery Point Objective", desc: "How much data you can afford to lose. Example: RPO 5 minutes = backups/logs at least every 5 minutes.", lesson: 45, group: "Performance, Capacity & Reliability Numbers" },
  { term: "RTO", full: "Recovery Time Objective", desc: "How long you can afford to be down. Example: RTO 1 hour = must be back online within an hour.", lesson: 45, group: "Performance, Capacity & Reliability Numbers" },
  { term: "Headroom", aliases: ["headroom", "headrooms", "Headrooms"], full: "Headroom", desc: "Spare capacity for spikes and failures. Example: Running servers at 60% CPU, not 95%.", lesson: 8, group: "Performance, Capacity & Reliability Numbers", once: true },
  { term: "N+1 (capacity)", aliases: ["N+1"], full: "N+1 (capacity)", desc: "One more server than needed, to survive a failure. Example: Need 4 servers? Run 5.", lesson: 40, group: "Performance, Capacity & Reliability Numbers" },

  // ── Databases & Data ──────────────────────────────────────────────────
  { term: "SQL", full: "Structured Query Language", desc: "The language for relational databases. Example: SELECT name FROM users WHERE id = 42;.", lesson: 5, group: "Databases & Data" },
  { term: "RDBMS", full: "Relational Database Management System", desc: "A database of tables linked by keys. Example: PostgreSQL, MySQL, SQL Server.", lesson: 5, group: "Databases & Data" },
  { term: "NoSQL", full: "\"Not only SQL\"", desc: "Non-relational databases: key-value, document, wide-column, graph. Example: Redis, MongoDB, Cassandra, Neo4j.", lesson: 20, group: "Databases & Data" },
  { term: "PK / FK", aliases: ["PK", "FK"], full: "Primary Key / Foreign Key", desc: "PK uniquely identifies a row; FK points to a row in another table. Example: orders.user_id (FK) → users.id (PK).", lesson: 5, group: "Databases & Data" },
  { term: "Index", aliases: ["index", "indexs", "Indexs"], full: "Index", desc: "A structure that makes lookups fast. Example: The index at the back of a textbook.", lesson: 5, group: "Databases & Data", once: true },
  { term: "B-tree", aliases: ["b-tree", "b-trees", "B-trees"], full: "Balanced tree", desc: "A sorted, shallow tree used by most database indexes. Example: Finds 1 row among 1 billion in ~3–4 steps.", lesson: 22, group: "Databases & Data", once: true },
  { term: "LSM-tree", full: "Log-Structured Merge-tree", desc: "A write-optimised storage structure (memtable + sorted files + compaction). Example: Used by Cassandra, RocksDB, ScyllaDB.", lesson: 22, group: "Databases & Data" },
  { term: "SSTable", full: "Sorted String Table", desc: "An immutable, sorted file in LSM storage. Example: Written when the in-memory table fills up.", lesson: 22, group: "Databases & Data" },
  { term: "Bloom filter", aliases: ["bloom filter"], full: "Bloom filter", desc: "A tiny structure that says \"definitely not here\" or \"maybe here\". Example: Skips reading files that can't contain a key.", lesson: 16, group: "Databases & Data", once: true },
  { term: "ACID", full: "Atomicity, Consistency, Isolation, Durability", desc: "Guarantees that transactions are reliable. Example: A bank transfer: both debit and credit happen, or neither.", lesson: 21, group: "Databases & Data" },
  { term: "BASE", full: "Basically Available, Soft state, Eventually consistent", desc: "A looser model favouring availability. Example: Many NoSQL systems.", lesson: 21, group: "Databases & Data" },
  { term: "Transaction", aliases: ["transaction", "transactions", "Transactions"], full: "Transaction", desc: "A group of changes that succeed or fail together. Example: BEGIN … COMMIT.", lesson: 21, group: "Databases & Data", once: true },
  { term: "Isolation levels", aliases: ["isolation levels"], full: "Isolation levels", desc: "How much concurrent transactions can see of each other. Example: Read Committed, Repeatable Read, Serializable.", lesson: 21, group: "Databases & Data", once: true },
  { term: "MVCC", full: "Multi-Version Concurrency Control", desc: "Keeps several versions of rows so readers don't block writers. Example: PostgreSQL shows each transaction a consistent snapshot.", lesson: 21, group: "Databases & Data" },
  { term: "WAL", full: "Write-Ahead Log", desc: "Changes are written to a log before the data files. Example: Makes crash recovery and replication possible.", lesson: 21, group: "Databases & Data" },
  { term: "OLTP", full: "Online Transaction Processing", desc: "Many small, fast reads/writes. Example: Placing orders, updating profiles.", lesson: 5, group: "Databases & Data" },
  { term: "OLAP", full: "Online Analytical Processing", desc: "Big queries over lots of data. Example: \"Revenue by city for last year.\".", lesson: 5, group: "Databases & Data" },
  { term: "ORM", full: "Object-Relational Mapper", desc: "Maps database rows to code objects. Example: Prisma, Django ORM, Hibernate.", lesson: 5, group: "Databases & Data" },
  { term: "N+1 problem", full: "N+1 problem", desc: "One query plus N more, one per item. Example: Loading 20 posts, then 20 separate author queries.", lesson: 5, group: "Databases & Data" },
  { term: "Normalization", aliases: ["normalization", "normalizations", "Normalizations"], full: "Normalization", desc: "Storing each fact once, to avoid inconsistencies. Example: Customer city stored only in customers.", lesson: 23, group: "Databases & Data", once: true },
  { term: "Denormalization", aliases: ["denormalization", "denormalizations", "Denormalizations"], full: "Denormalization", desc: "Copying data on purpose for faster reads. Example: Storing author_name in each post.", lesson: 23, group: "Databases & Data", once: true },
  { term: "Materialized view", aliases: ["materialized view"], full: "Materialized view", desc: "A stored, precomputed query result. Example: A daily sales summary table.", lesson: 23, group: "Databases & Data", once: true },
  { term: "CDC", full: "Change Data Capture", desc: "Streams every database change as an event. Example: Debezium sends DB changes to Kafka → search index.", lesson: 19, group: "Databases & Data" },
  { term: "ETL / ELT", aliases: ["ETL", "ELT"], full: "Extract, Transform, Load", desc: "Moving data from sources into a warehouse. Example: Nightly copy of orders into BigQuery.", group: "Databases & Data" },
  { term: "Data warehouse", aliases: ["data warehouse"], full: "Data warehouse", desc: "A database built for analytics. Example: BigQuery, Snowflake, Redshift, ClickHouse.", lesson: 29, group: "Databases & Data", once: true },
  { term: "PITR", full: "Point-In-Time Recovery", desc: "Restore a database to any exact moment. Example: Restore to 10:41:59, one second before a bad DELETE.", lesson: 45, group: "Databases & Data" },
  { term: "Schema", aliases: ["schema", "schemas", "Schemas"], full: "Schema", desc: "The structure of data (tables, fields, types). Example: users(id, email, name).", lesson: 20, group: "Databases & Data", once: true },
  { term: "UUID", full: "Universally Unique Identifier", desc: "A 128-bit ID that's unique without coordination. Example: 7f3c9a2e-4b1d-4e8a-9f0c-2d6b1e5a8c33.", lesson: 5, group: "Databases & Data" },
  { term: "Snowflake ID", full: "Snowflake ID", desc: "64-bit ID = timestamp + machine ID + sequence. Example: Unique, time-ordered IDs generated on any server.", lesson: 25, group: "Databases & Data" },

  // ── Distributed Systems ───────────────────────────────────────────────
  { term: "Replication", aliases: ["replication", "replications", "Replications"], full: "Replication", desc: "Keeping copies of data on several machines. Example: A primary database plus 3 read replicas.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Leader / Follower", aliases: ["Leader", "leader", "leaders", "Leaders", "Follower", "follower", "followers", "Followers"], full: "also Primary / Replica", desc: "The leader accepts writes; followers copy them. Example: All writes go to the primary; reads can go to replicas.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Replication lag", aliases: ["replication lag"], full: "Replication lag", desc: "How far behind a replica is. Example: You update your bio, refresh, and see the old one.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Failover", aliases: ["failover", "failovers", "Failovers"], full: "Failover", desc: "Switching to a backup when the main one fails. Example: A replica becomes the new primary.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Split brain", aliases: ["split brain"], full: "Split brain", desc: "Two nodes both think they're the leader. Example: Both accept writes, so the data diverges.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Quorum", aliases: ["quorum", "quorums", "Quorums"], full: "Quorum", desc: "A majority (or W + R > N) must agree. Example: 3 replicas: write to 2, read from 2 → always see the latest.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Consensus", aliases: ["consensus"], full: "Consensus", desc: "Getting machines to agree on one value despite failures. Example: Electing exactly one leader.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Raft / Paxos", aliases: ["Raft", "raft", "rafts", "Rafts", "Paxos", "paxos"], full: "Raft / Paxos", desc: "Well-known consensus algorithms. Example: Used by etcd, Consul, CockroachDB.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Sharding / Partitioning", aliases: ["Sharding", "sharding", "shardings", "Shardings", "Partitioning", "partitioning", "partitionings", "Partitionings"], full: "Sharding / Partitioning", desc: "Splitting data across machines. Example: Users 1–1M on shard 1, 1M–2M on shard 2.", lesson: 25, group: "Distributed Systems", once: true },
  { term: "Shard key", aliases: ["shard key"], full: "Shard key", desc: "The field that decides which shard holds a row. Example: tenant_id in a SaaS app.", lesson: 25, group: "Distributed Systems", once: true },
  { term: "Hot key / hot spot", aliases: ["Hot key", "hot key", "hot spot", "Hot spot"], full: "Hot key / hot spot", desc: "One key or shard getting far more traffic than others. Example: A celebrity's profile.", lesson: 16, group: "Distributed Systems", once: true },
  { term: "Consistent hashing", aliases: ["consistent hashing"], full: "Consistent hashing", desc: "Places keys and servers on a ring so few keys move when servers change. Example: Adding a cache server moves only ~1/N of keys.", lesson: 26, group: "Distributed Systems", once: true },
  { term: "Virtual nodes", aliases: ["virtual nodes"], full: "vnodes", desc: "Each server appears many times on the hash ring. Example: Spreads load evenly.", lesson: 26, group: "Distributed Systems", once: true },
  { term: "CAP theorem", full: "Consistency, Availability, Partition tolerance", desc: "During a network partition, choose consistency or availability. Example: Bank: refuse (C) vs allow a possibly wrong balance (A).", lesson: 27, group: "Distributed Systems" },
  { term: "PACELC", full: "Partition → Availability or Consistency; Else → Latency or Consistency", desc: "Adds the everyday latency vs consistency trade-off. Example: Strong consistency across continents is slower.", lesson: 27, group: "Distributed Systems" },
  { term: "Linearizability", aliases: ["linearizability", "linearizabilitys", "Linearizabilitys"], full: "Linearizability", desc: "The strongest consistency: acts like one copy. Example: Once anyone sees the new value, nobody sees the old.", lesson: 28, group: "Distributed Systems", once: true },
  { term: "Eventual consistency", aliases: ["eventual consistency"], full: "Eventual consistency", desc: "Copies agree eventually, if updates stop. Example: Like counts that differ briefly between devices.", lesson: 28, group: "Distributed Systems", once: true },
  { term: "Read-your-writes", aliases: ["read-your-writes"], full: "Read-your-writes", desc: "You always see your own changes. Example: Your new comment doesn't disappear on refresh.", lesson: 28, group: "Distributed Systems", once: true },
  { term: "LWW", full: "Last-Write-Wins", desc: "Keep the update with the latest timestamp. Example: Simple conflict resolution; may lose the other write.", lesson: 28, group: "Distributed Systems" },
  { term: "Vector clock", aliases: ["vector clock"], full: "Vector clock", desc: "Tracks versions per node to detect concurrent updates. Example: Amazon's Dynamo used them for cart conflicts.", lesson: 28, group: "Distributed Systems", once: true },
  { term: "CRDT", full: "Conflict-free Replicated Data Type", desc: "Data types that always merge correctly. Example: Collaborative counters or shared documents.", lesson: 28, group: "Distributed Systems" },
  { term: "HLC", full: "Hybrid Logical Clock", desc: "Combines wall-clock time and a counter for ordering. Example: Used by CockroachDB.", lesson: 28, group: "Distributed Systems" },
  { term: "2PC", full: "Two-Phase Commit", desc: "Coordinates a transaction across systems (prepare, then commit). Example: Slow and fragile; often avoided in microservices.", lesson: 21, group: "Distributed Systems" },
  { term: "Saga", aliases: ["saga", "sagas", "Sagas"], full: "Saga", desc: "A sequence of local transactions with compensating actions. Example: Payment fails → release stock → cancel order.", lesson: 39, group: "Distributed Systems", once: true },
  { term: "Fencing", aliases: ["fencing", "fencings", "Fencings"], full: "Fencing", desc: "Stops an old leader from writing after failover. Example: Revoking the old primary's access.", lesson: 24, group: "Distributed Systems", once: true },
  { term: "Gossip", aliases: ["gossip", "gossips", "Gossips"], full: "Gossip", desc: "Nodes share information with random peers, spreading it like rumours. Example: Cassandra nodes learning cluster membership.", group: "Distributed Systems", once: true },

  // ── Caching & Storage ─────────────────────────────────────────────────
  { term: "Cache", aliases: ["cache", "caches", "Caches"], full: "Cache", desc: "A fast copy of frequently used data. Example: Salt kept on the kitchen counter instead of in the storeroom.", lesson: 15, group: "Caching & Storage", once: true },
  { term: "Cache hit / miss", aliases: ["Cache hit", "cache hit", "miss", "Miss"], full: "Cache hit / miss", desc: "Found in cache / not found. Example: Hit: 1 ms from Redis. Miss: 50 ms from the database.", lesson: 15, group: "Caching & Storage", once: true },
  { term: "Hit ratio", aliases: ["hit ratio"], full: "Hit ratio", desc: "% of requests served by the cache. Example: 95% hit ratio → only 5% reach the database.", lesson: 15, group: "Caching & Storage", once: true },
  { term: "Cache-aside", aliases: ["cache-aside", "cache-asides", "Cache-asides"], full: "lazy loading", desc: "App reads cache → on miss, loads DB and fills cache. Example: The most common caching pattern.", lesson: 16, group: "Caching & Storage", once: true },
  { term: "Write-through / Write-behind", aliases: ["Write-through", "write-through", "write-throughs", "Write-throughs", "Write-behind", "write-behind", "write-behinds", "Write-behinds"], full: "Write-through / Write-behind", desc: "Write to cache and DB together / write to cache first, DB later. Example: Write-behind for view counters.", lesson: 16, group: "Caching & Storage", once: true },
  { term: "LRU / LFU", aliases: ["LRU", "LFU"], full: "Least Recently / Frequently Used", desc: "Eviction rules for full caches. Example: LRU removes the item not used for the longest time.", lesson: 16, group: "Caching & Storage" },
  { term: "Cache stampede", aliases: ["cache stampede"], full: "thundering herd", desc: "Many requests rebuild the same expired key at once. Example: A popular key expires → 5,000 DB queries in 1 second.", lesson: 16, group: "Caching & Storage", once: true },
  { term: "Redis", aliases: ["redis"], full: "Remote Dictionary Server", desc: "An in-memory data store: cache, counters, sessions, queues. Example: Storing sessions and rate-limit counters.", lesson: 15, group: "Caching & Storage", once: true },
  { term: "Memcached", aliases: ["memcached", "memcacheds", "Memcacheds"], full: "Memcached", desc: "A simple, fast in-memory cache. Example: Facebook's huge caching layer.", lesson: 15, group: "Caching & Storage", once: true },
  { term: "CDN", full: "Content Delivery Network", desc: "Servers worldwide that cache content near users. Example: Images load from a server in your city.", lesson: 14, group: "Caching & Storage" },
  { term: "Object storage", aliases: ["object storage"], full: "Object storage", desc: "Stores files (\"objects\") by key over HTTP, at huge scale. Example: Amazon S3, Google Cloud Storage.", lesson: 17, group: "Caching & Storage", once: true },
  { term: "S3", full: "Simple Storage Service", desc: "Amazon's object storage (and the de facto API standard). Example: Profile photos and backups.", lesson: 17, group: "Caching & Storage" },
  { term: "Blob", aliases: ["blob", "blobs", "Blobs"], full: "Binary Large Object", desc: "Any large binary file. Example: A video or image.", lesson: 17, group: "Caching & Storage", once: true },
  { term: "Block storage", aliases: ["block storage"], full: "Block storage", desc: "A raw disk attached to a server. Example: AWS EBS volume for a database.", lesson: 17, group: "Caching & Storage", once: true },
  { term: "Pre-signed URL", full: "Pre-signed URL", desc: "A temporary, signed link to upload/download one file. Example: Browser uploads a photo directly to S3.", lesson: 17, group: "Caching & Storage" },
  { term: "Erasure coding", aliases: ["erasure coding"], full: "Erasure coding", desc: "Splits data into pieces + parity so it survives lost pieces. Example: Object storage durability with less space than 3 full copies.", lesson: 17, group: "Caching & Storage", once: true },
  { term: "Key-value store", aliases: ["key-value store"], full: "KV store", desc: "Stores values by key. Example: session:abc → {user: 42}.", lesson: 20, group: "Caching & Storage", once: true },
  { term: "Inverted index", aliases: ["inverted index"], full: "Inverted index", desc: "Maps words to the documents containing them. Example: \"shoe\" → docs 1, 3. Powers search engines.", lesson: 19, group: "Caching & Storage", once: true },
  { term: "BM25", full: "Best Match 25", desc: "A standard formula for ranking search results. Example: Default ranking in Elasticsearch.", lesson: 19, group: "Caching & Storage" },

  // ── Messaging & Events ────────────────────────────────────────────────
  { term: "MQ", full: "Message Queue", desc: "Holds messages until workers process them. Example: Order placed → email job in the queue.", lesson: 18, group: "Messaging & Events" },
  { term: "Producer / Consumer", aliases: ["Producer", "producer", "producers", "Producers", "Consumer", "consumer", "consumers", "Consumers"], full: "Producer / Consumer", desc: "Sends messages / processes messages. Example: API = producer; email worker = consumer.", lesson: 18, group: "Messaging & Events", once: true },
  { term: "Pub/Sub", aliases: ["Pub", "pub", "pubs", "Pubs", "Sub", "sub", "subs", "Subs"], full: "Publish/Subscribe", desc: "One message delivered to every subscriber. Example: \"Order placed\" → email, warehouse and analytics all get it.", lesson: 35, group: "Messaging & Events", once: true },
  { term: "Competing consumers", aliases: ["competing consumers"], full: "Competing consumers", desc: "Many workers share one queue; each message goes to one worker. Example: 5 email workers processing one queue.", lesson: 18, group: "Messaging & Events", once: true },
  { term: "Kafka", aliases: ["kafka", "kafkas", "Kafkas"], full: "Apache Kafka", desc: "A distributed, durable log for event streaming. Example: LinkedIn's activity events; CDC pipelines.", lesson: 36, group: "Messaging & Events", once: true },
  { term: "Topic / Partition", aliases: ["Topic", "topic", "topics", "Topics", "Partition", "partition", "partitions", "Partitions"], full: "Topic / Partition", desc: "A named stream / an ordered slice of it. Example: Topic orders, partitioned by order ID.", lesson: 36, group: "Messaging & Events", once: true },
  { term: "Offset", aliases: ["offset", "offsets", "Offsets"], full: "Offset", desc: "A message's position in a partition. Example: \"I've processed up to offset 1,041.\".", lesson: 36, group: "Messaging & Events", once: true },
  { term: "Consumer group", aliases: ["consumer group"], full: "Consumer group", desc: "Consumers sharing the work of reading a topic. Example: Group \"billing\" and group \"analytics\" each read every event.", lesson: 36, group: "Messaging & Events", once: true },
  { term: "Consumer lag", aliases: ["consumer lag"], full: "Consumer lag", desc: "How far behind a consumer is. Example: Rising lag = consumers can't keep up.", lesson: 36, group: "Messaging & Events", once: true },
  { term: "Ack", aliases: ["ack", "acks", "Acks"], full: "Acknowledgement", desc: "\"I received / processed this.\" Example: Worker acks after sending the email.", lesson: 18, group: "Messaging & Events", once: true },
  { term: "At-most-once / At-least-once / Exactly-once", aliases: ["At-most-once", "at-most-once", "at-most-onces", "At-most-onces", "At-least-once", "at-least-once", "at-least-onces", "At-least-onces", "Exactly-once", "exactly-once", "exactly-onces", "Exactly-onces"], full: "At-most-once / At-least-once / Exactly-once", desc: "Delivery guarantees: may lose / may duplicate / effectively once. Example: Payments need at-least-once + dedup.", lesson: 37, group: "Messaging & Events", once: true },
  { term: "EOS", full: "Exactly-Once Semantics", desc: "Kafka's feature for exactly-once processing within Kafka. Example: Read → process → write back to Kafka atomically.", lesson: 37, group: "Messaging & Events" },
  { term: "DLQ", full: "Dead-Letter Queue", desc: "Where messages go after failing too many times. Example: Malformed messages parked for engineers to inspect.", lesson: 38, group: "Messaging & Events" },
  { term: "Outbox pattern", aliases: ["outbox pattern"], full: "transactional outbox", desc: "Save data + \"event to publish\" in one DB transaction. Example: Solves \"DB updated but event not sent\".", lesson: 37, group: "Messaging & Events", once: true },
  { term: "Event sourcing", aliases: ["event sourcing"], full: "Event sourcing", desc: "Store every change as an event; state = replay of events. Example: A bank ledger.", lesson: 39, group: "Messaging & Events", once: true },
  { term: "CQRS", full: "Command Query Responsibility Segregation", desc: "Separate models for writes and reads. Example: Writes to PostgreSQL; reads from a search index.", lesson: 39, group: "Messaging & Events" },
  { term: "Backpressure", aliases: ["backpressure", "backpressures", "Backpressures"], full: "Backpressure", desc: "Slowing producers when consumers can't keep up. Example: Rejecting non-urgent jobs when the queue is too long.", lesson: 18, group: "Messaging & Events", once: true },
  { term: "Fan-out", aliases: ["fan-out", "fan-outs", "Fan-outs"], full: "Fan-out", desc: "One event/message spread to many recipients. Example: One post → written into 200 followers' feeds.", lesson: 64, group: "Messaging & Events", once: true },
  { term: "Cron", aliases: ["cron", "crons", "Crons"], full: "from \"chronos\", time", desc: "Runs jobs on a schedule. Example: \"Every night at 2 AM, clean expired sessions.\".", lesson: 38, group: "Messaging & Events", once: true },

  // ── Reliability & Resilience Patterns ─────────────────────────────────
  { term: "HA", full: "High Availability", desc: "Designing to minimise downtime. Example: Servers in 3 zones with automatic failover.", lesson: 40, group: "Reliability & Resilience Patterns" },
  { term: "SPOF", full: "Single Point Of Failure", desc: "A part whose failure brings everything down. Example: One database with no replica.", lesson: 40, group: "Reliability & Resilience Patterns" },
  { term: "Redundancy", aliases: ["redundancy", "redundancys", "Redundancys"], full: "Redundancy", desc: "Having spares of critical parts. Example: Two load balancers, three app servers.", lesson: 40, group: "Reliability & Resilience Patterns", once: true },
  { term: "Active-active / Active-passive", aliases: ["Active-active", "active-active", "active-actives", "Active-actives", "Active-passive", "active-passive", "active-passives", "Active-passives"], full: "Active-active / Active-passive", desc: "Both copies serve traffic / one waits as backup. Example: Two regions serving users vs a standby region.", lesson: 40, group: "Reliability & Resilience Patterns", once: true },
  { term: "Health check", aliases: ["health check"], full: "Health check", desc: "Regularly checking whether an instance works. Example: Load balancer calls /health every 5 seconds.", lesson: 12, group: "Reliability & Resilience Patterns", once: true },
  { term: "Timeout", aliases: ["timeout", "timeouts", "Timeouts"], full: "Timeout", desc: "Maximum time to wait for a response. Example: Give up on a call after 500 ms.", lesson: 41, group: "Reliability & Resilience Patterns", once: true },
  { term: "Retry", aliases: ["retry", "retrys", "Retrys"], full: "Retry", desc: "Trying a failed operation again. Example: Retry once after a network blip.", lesson: 41, group: "Reliability & Resilience Patterns", once: true },
  { term: "Exponential backoff", aliases: ["exponential backoff"], full: "Exponential backoff", desc: "Waiting longer after each failure. Example: 100 ms, 200 ms, 400 ms….", lesson: 41, group: "Reliability & Resilience Patterns", once: true },
  { term: "Jitter", aliases: ["jitter", "jitters", "Jitters"], full: "Jitter", desc: "Random extra delay so clients don't retry together. Example: Waits spread between 0 and 400 ms.", lesson: 41, group: "Reliability & Resilience Patterns", once: true },
  { term: "Circuit breaker", aliases: ["circuit breaker"], full: "Circuit breaker", desc: "Stops calling a failing service for a while. Example: Like a home electrical breaker tripping.", lesson: 42, group: "Reliability & Resilience Patterns", once: true },
  { term: "Bulkhead", aliases: ["bulkhead", "bulkheads", "Bulkheads"], full: "Bulkhead", desc: "Separate resource pools so one failure can't sink everything. Example: A ship's watertight compartments.", lesson: 42, group: "Reliability & Resilience Patterns", once: true },
  { term: "Fallback", aliases: ["fallback", "fallbacks", "Fallbacks"], full: "Fallback", desc: "What to return when something fails. Example: Show \"popular items\" when recommendations are down.", lesson: 42, group: "Reliability & Resilience Patterns", once: true },
  { term: "Token bucket / Leaky bucket", aliases: ["Token bucket", "token bucket", "Leaky bucket", "leaky bucket"], full: "Token bucket / Leaky bucket", desc: "Rate-limiting algorithms. Example: 20-token bucket refilled at 10/s allows bursts.", lesson: 43, group: "Reliability & Resilience Patterns", once: true },
  { term: "Load shedding", aliases: ["load shedding"], full: "Load shedding", desc: "Rejecting excess requests to protect the system. Example: Returning 503 to low-priority traffic during overload.", lesson: 44, group: "Reliability & Resilience Patterns", once: true },
  { term: "Graceful degradation", aliases: ["graceful degradation"], full: "Graceful degradation", desc: "Turning off non-essential features under stress. Example: Hide reviews, keep checkout working.", lesson: 44, group: "Reliability & Resilience Patterns", once: true },
  { term: "Kill switch / Feature flag", aliases: ["Kill switch", "kill switch", "Feature flag", "feature flag"], full: "Kill switch / Feature flag", desc: "A switch to turn a feature on/off without deploying. Example: Disable a broken feature instantly.", lesson: 44, group: "Reliability & Resilience Patterns", once: true },
  { term: "Chaos engineering", aliases: ["chaos engineering"], full: "Chaos engineering", desc: "Deliberately injecting failures to test resilience. Example: Netflix's Chaos Monkey kills random servers.", lesson: 40, group: "Reliability & Resilience Patterns", once: true },
  { term: "DR", full: "Disaster Recovery", desc: "Plans and systems to recover from major disasters. Example: Restoring in another region after a data-centre fire.", lesson: 45, group: "Reliability & Resilience Patterns" },
  { term: "3-2-1 rule", full: "3-2-1 rule", desc: "3 copies, 2 media types, 1 off-site. Example: Database + backup in same cloud + backup in another region.", lesson: 45, group: "Reliability & Resilience Patterns" },
  { term: "Static stability", aliases: ["static stability"], full: "Static stability", desc: "Keeps working during a failure without needing changes. Example: Enough servers already running in each zone.", lesson: 40, group: "Reliability & Resilience Patterns", once: true },
  { term: "Blast radius", aliases: ["blast radius"], full: "Blast radius", desc: "How much is affected by one failure. Example: A bad deploy in one \"cell\" affects only that cell's users.", lesson: 40, group: "Reliability & Resilience Patterns", once: true },

  // ── Observability & Operations ────────────────────────────────────────
  { term: "Observability", aliases: ["observability", "observabilitys", "Observabilitys"], full: "Observability", desc: "Understanding a system's internal state from its outputs. Example: Answering \"why is checkout slow for Android users?\".", lesson: 46, group: "Observability & Operations", once: true },
  { term: "Logs", aliases: ["logs"], full: "Logs", desc: "Timestamped records of events. Example: {\"level\":\"error\",\"msg\":\"payment failed\",\"order\":\"5521\"}.", lesson: 46, group: "Observability & Operations", once: true },
  { term: "Metrics", aliases: ["metrics"], full: "Metrics", desc: "Numbers measured over time. Example: Requests per second, p99 latency, error rate.", lesson: 46, group: "Observability & Operations", once: true },
  { term: "Traces / Spans", aliases: ["Traces", "traces", "Spans", "spans"], full: "Traces / Spans", desc: "The path of one request across services / one step in it. Example: See that the payment call took 3 of the 3.2 seconds.", lesson: 46, group: "Observability & Operations", once: true },
  { term: "Trace ID / Correlation ID", aliases: ["Trace ID", "Correlation ID"], full: "Trace ID / Correlation ID", desc: "An ID shared across all logs and spans of one request. Example: Search logs by trace_id to follow one checkout.", lesson: 46, group: "Observability & Operations" },
  { term: "OTel", full: "OpenTelemetry", desc: "Open standard for producing logs, metrics and traces. Example: Instrument once, send data to any tool.", lesson: 46, group: "Observability & Operations" },
  { term: "APM", full: "Application Performance Monitoring", desc: "Tools for tracing and app performance. Example: Datadog, New Relic, Dynatrace.", lesson: 46, group: "Observability & Operations" },
  { term: "RUM", full: "Real User Monitoring", desc: "Measures what real users' browsers/apps experience. Example: Page load times by country and device.", lesson: 48, group: "Observability & Operations" },
  { term: "Synthetic monitoring", aliases: ["synthetic monitoring"], full: "Synthetic monitoring", desc: "Scripted \"robot users\" that test the site constantly. Example: A bot that logs in and checks out every minute.", lesson: 48, group: "Observability & Operations", once: true },
  { term: "Golden Signals", full: "Golden Signals", desc: "Latency, traffic, errors, saturation. Example: The four core metrics for any service.", lesson: 46, group: "Observability & Operations" },
  { term: "RED", full: "Rate, Errors, Duration", desc: "Key metrics for request-driven services. Example: 500 req/s, 0.2% errors, p99 180 ms.", lesson: 46, group: "Observability & Operations" },
  { term: "USE", full: "Utilisation, Saturation, Errors", desc: "Key metrics for resources (CPU, disk, network). Example: CPU 70%, 12 requests waiting, 0 errors.", lesson: 46, group: "Observability & Operations" },
  { term: "Cardinality", aliases: ["cardinality", "cardinalitys", "Cardinalitys"], full: "Cardinality", desc: "Number of unique label combinations in metrics. Example: Adding user_id as a label creates millions of series.", lesson: 46, group: "Observability & Operations", once: true },
  { term: "SRE", full: "Site Reliability Engineering", desc: "Applying software engineering to operations. Example: Google's SLOs, error budgets, postmortems.", lesson: 47, group: "Observability & Operations" },
  { term: "On-call", aliases: ["on-call", "on-calls", "On-calls"], full: "On-call", desc: "Engineers responsible for responding to alerts. Example: Weekly rotation with primary and secondary.", lesson: 48, group: "Observability & Operations", once: true },
  { term: "Runbook", aliases: ["runbook", "runbooks", "Runbooks"], full: "Runbook", desc: "Step-by-step instructions for handling an alert. Example: \"If checkout errors spike: check deploys, then…\".", lesson: 48, group: "Observability & Operations", once: true },
  { term: "Incident / SEV", aliases: ["Incident", "incident", "incidents", "Incidents", "SEV"], full: "Severity level", desc: "An unplanned problem, ranked by impact. Example: SEV1 = payments down for many users.", lesson: 48, group: "Observability & Operations", once: true },
  { term: "IC", full: "Incident Commander", desc: "The person coordinating an incident. Example: Makes decisions; doesn't debug.", lesson: 48, group: "Observability & Operations" },
  { term: "Postmortem", aliases: ["postmortem", "postmortems", "Postmortems"], full: "incident review", desc: "A written analysis of what happened and how to prevent it. Example: Blameless report with action items.", lesson: 48, group: "Observability & Operations", once: true },

  // ── Security & Identity ───────────────────────────────────────────────
  { term: "AuthN", full: "Authentication", desc: "Proves who you are. Example: Logging in with password + OTP.", lesson: 49, group: "Security & Identity" },
  { term: "AuthZ", full: "Authorization", desc: "Decides what you're allowed to do. Example: You can see your invoices, not other people's.", lesson: 49, group: "Security & Identity" },
  { term: "TLS", full: "Transport Layer Security", desc: "Encrypts data between two parties and verifies the server. Example: The \"S\" in HTTPS.", lesson: 3, group: "Security & Identity" },
  { term: "SSL", full: "Secure Sockets Layer", desc: "The old, insecure predecessor of TLS (the name is still used loosely). Example: \"SSL certificate\" usually means a TLS certificate.", lesson: 3, group: "Security & Identity" },
  { term: "mTLS", full: "Mutual TLS", desc: "Both sides present certificates. Example: Service A and service B verify each other.", lesson: 51, group: "Security & Identity" },
  { term: "PKI / CA", aliases: ["PKI", "CA"], full: "Public Key Infrastructure / Certificate Authority", desc: "The system of trusted certificates / an organisation that issues them. Example: Let's Encrypt issues free certificates.", lesson: 3, group: "Security & Identity" },
  { term: "Session", aliases: ["session", "sessions", "Sessions"], full: "Session", desc: "Server-side record of a logged-in user. Example: Session ID in a cookie → user data in Redis.", lesson: 49, group: "Security & Identity", once: true },
  { term: "Cookie", aliases: ["cookie", "cookies", "Cookies"], full: "Cookie", desc: "Small data the browser sends with each request to a site. Example: sid=k9Fq…; HttpOnly; Secure; SameSite=Lax.", lesson: 49, group: "Security & Identity", once: true },
  { term: "JWT", full: "JSON Web Token", desc: "A signed token containing claims about a user. Example: header.payload.signature sent in Authorization: Bearer.", lesson: 49, group: "Security & Identity" },
  { term: "OAuth 2.0", full: "Open Authorization", desc: "Lets apps get limited access to your data without your password. Example: \"Allow this app to read your Google Photos\".", lesson: 50, group: "Security & Identity" },
  { term: "OIDC", full: "OpenID Connect", desc: "Adds login (identity) on top of OAuth 2.0. Example: \"Sign in with Google\".", lesson: 50, group: "Security & Identity" },
  { term: "PKCE", full: "Proof Key for Code Exchange", desc: "Protects the OAuth code exchange from interception. Example: Required for mobile and single-page apps.", lesson: 50, group: "Security & Identity" },
  { term: "SSO", full: "Single Sign-On", desc: "Log in once, access many apps. Example: Company login gives access to email, Slack and HR tools.", lesson: 50, group: "Security & Identity" },
  { term: "SAML", full: "Security Assertion Markup Language", desc: "An older XML-based SSO standard, common in enterprises. Example: Logging into company tools via Okta.", lesson: 50, group: "Security & Identity" },
  { term: "MFA / 2FA", aliases: ["MFA", "2FA"], full: "Multi-Factor / Two-Factor Authentication", desc: "Requires more than a password. Example: Password + code from an app.", lesson: 49, group: "Security & Identity" },
  { term: "OTP / TOTP", aliases: ["OTP", "TOTP"], full: "One-Time Password / Time-based OTP", desc: "A short-lived code. Example: 6-digit SMS code; authenticator app code that changes every 30 s.", lesson: 49, group: "Security & Identity" },
  { term: "Passkey", aliases: ["passkey", "passkeys", "Passkeys"], full: "WebAuthn / FIDO2", desc: "Passwordless login using device cryptography. Example: Unlock with fingerprint; nothing to phish.", lesson: 49, group: "Security & Identity", once: true },
  { term: "RBAC / ABAC / ReBAC", aliases: ["RBAC", "ABAC", "ReBAC"], full: "Role- / Attribute- / Relationship-Based Access Control", desc: "Ways to model permissions. Example: RBAC: \"editors can edit\". ReBAC: \"team members can view team docs\".", lesson: 49, group: "Security & Identity" },
  { term: "ACL", full: "Access Control List", desc: "A list of who can do what on a resource. Example: File shared with Asha (edit) and Ravi (view).", lesson: 49, group: "Security & Identity" },
  { term: "IAM", full: "Identity and Access Management", desc: "Managing users, roles and permissions (especially in cloud). Example: An AWS role allowing a service to read one bucket.", lesson: 51, group: "Security & Identity" },
  { term: "Least privilege", aliases: ["least privilege"], full: "Least privilege", desc: "Give only the minimum permissions needed. Example: The app's DB user can't drop tables.", lesson: 49, group: "Security & Identity", once: true },
  { term: "Zero trust", aliases: ["zero trust"], full: "Zero trust", desc: "Never trust the network; verify every connection. Example: Encrypt and authenticate even internal traffic.", lesson: 51, group: "Security & Identity", once: true },
  { term: "AES", full: "Advanced Encryption Standard", desc: "Fast symmetric encryption. Example: Encrypting files and database fields.", lesson: 51, group: "Security & Identity" },
  { term: "RSA / ECC", aliases: ["RSA", "ECC"], full: "Rivest–Shamir–Adleman / Elliptic Curve Cryptography", desc: "Public-key cryptography. Example: Key exchange and signatures in TLS.", lesson: 51, group: "Security & Identity" },
  { term: "SHA-256", full: "Secure Hash Algorithm", desc: "A one-way fingerprint of data. Example: Checking a download wasn't altered.", lesson: 51, group: "Security & Identity" },
  { term: "HMAC", full: "Hash-based Message Authentication Code", desc: "Proves a message wasn't changed and came from a key holder. Example: Signing webhooks.", lesson: 34, group: "Security & Identity" },
  { term: "Argon2 / bcrypt", aliases: ["Argon2", "bcrypt", "Bcrypt", "bcrypts"], full: "Argon2 / bcrypt", desc: "Slow, salted password-hashing algorithms. Example: Storing passwords safely.", lesson: 49, group: "Security & Identity", once: true },
  { term: "KMS / HSM", aliases: ["KMS", "HSM"], full: "Key Management Service / Hardware Security Module", desc: "Securely store and use encryption keys. Example: AWS KMS encrypts data keys; keys never leave it.", lesson: 51, group: "Security & Identity" },
  { term: "Envelope encryption", aliases: ["envelope encryption"], full: "Envelope encryption", desc: "Data encrypted with a data key; data key encrypted with a master key. Example: Cheap key rotation.", lesson: 51, group: "Security & Identity", once: true },
  { term: "E2EE", full: "End-to-End Encryption", desc: "Only sender and recipient can read messages. Example: WhatsApp chats.", lesson: 51, group: "Security & Identity" },
  { term: "Tokenisation", aliases: ["tokenisation", "tokenisations", "Tokenisations"], full: "Tokenisation", desc: "Replaces sensitive data with a meaningless token. Example: Saved card = tok_9f3a…, not the real number.", lesson: 51, group: "Security & Identity", once: true },
  { term: "TDE", full: "Transparent Data Encryption", desc: "Database encrypts its files and backups automatically. Example: Protects stolen disks, but not someone who can query the DB.", lesson: 51, group: "Security & Identity" },
  { term: "WAF", full: "Web Application Firewall", desc: "Filters malicious HTTP requests. Example: Blocking common SQL injection patterns at the edge.", lesson: 14, group: "Security & Identity" },
  { term: "DDoS", full: "Distributed Denial of Service", desc: "Flooding a service with traffic from many machines. Example: The 2016 Dyn attack.", lesson: 1, group: "Security & Identity" },
  { term: "OWASP", full: "Open Worldwide Application Security Project", desc: "Community known for the Top 10 web security risks. Example: Broken access control, injection, SSRF….", lesson: 52, group: "Security & Identity" },
  { term: "XSS", full: "Cross-Site Scripting", desc: "Attacker's script runs in other users' browsers. Example: A malicious comment that steals tokens.", lesson: 52, group: "Security & Identity" },
  { term: "CSRF", full: "Cross-Site Request Forgery", desc: "Tricks your browser into sending requests with your cookies. Example: A hidden form that transfers money.", lesson: 49, group: "Security & Identity" },
  { term: "SQLi", full: "SQL Injection", desc: "Input is treated as SQL code. Example: ' OR '1'='1 returns every user.", lesson: 52, group: "Security & Identity" },
  { term: "SSRF", full: "Server-Side Request Forgery", desc: "Tricks a server into requesting internal resources. Example: Fetching cloud metadata credentials.", lesson: 52, group: "Security & Identity" },
  { term: "IDOR / BOLA", aliases: ["IDOR", "BOLA"], full: "Insecure Direct Object Reference / Broken Object-Level Authorization", desc: "Accessing other users' objects by changing an ID. Example: /invoices/1002 shows someone else's invoice.", lesson: 49, group: "Security & Identity" },
  { term: "CVE", full: "Common Vulnerabilities and Exposures", desc: "A public ID for a known vulnerability. Example: Log4Shell = CVE-2021-44228.", lesson: 52, group: "Security & Identity" },
  { term: "SBOM", full: "Software Bill of Materials", desc: "A list of all components in your software. Example: Quickly finding every service that uses Log4j.", lesson: 52, group: "Security & Identity" },
  { term: "SAST / DAST", aliases: ["SAST", "DAST"], full: "Static / Dynamic Application Security Testing", desc: "Scanning code / testing the running app for vulnerabilities. Example: CI scans every pull request.", lesson: 52, group: "Security & Identity" },
  { term: "PII", full: "Personally Identifiable Information", desc: "Data that identifies a person. Example: Name, phone, email, address, ID numbers.", lesson: 46, group: "Security & Identity" },
  { term: "GDPR / PCI DSS", aliases: ["GDPR", "PCI DSS"], full: "General Data Protection Regulation / Payment Card Industry Data Security Standard", desc: "Privacy law (EU) / card security standard. Example: Rules on consent, deletion and card data.", lesson: 51, group: "Security & Identity" },

  // ── Architecture, Containers & Deployment ─────────────────────────────
  { term: "LB", full: "Load Balancer", desc: "Spreads traffic across servers. Example: 3 app servers behind one address.", lesson: 12, group: "Architecture, Containers & Deployment" },
  { term: "Reverse proxy", aliases: ["reverse proxy"], full: "Reverse proxy", desc: "Sits in front of servers: TLS, caching, compression, routing. Example: NGINX in front of a Node.js app.", lesson: 13, group: "Architecture, Containers & Deployment", once: true },
  { term: "API gateway", full: "API gateway", desc: "Front door for APIs: auth, rate limits, routing. Example: /orders → order service, /users → user service.", lesson: 13, group: "Architecture, Containers & Deployment" },
  { term: "Monolith", aliases: ["monolith", "monoliths", "Monoliths"], full: "Monolith", desc: "One application deployed as a single unit. Example: One Rails or Django app with one database.", lesson: 53, group: "Architecture, Containers & Deployment", once: true },
  { term: "Modular monolith", aliases: ["modular monolith"], full: "Modular monolith", desc: "One deployable with strong internal boundaries. Example: Shopify's large Rails app.", lesson: 53, group: "Architecture, Containers & Deployment", once: true },
  { term: "Microservices", aliases: ["microservices"], full: "Microservices", desc: "Many small, independently deployable services. Example: Separate user, order and payment services.", lesson: 53, group: "Architecture, Containers & Deployment", once: true },
  { term: "SOA", full: "Service-Oriented Architecture", desc: "An earlier style of building systems from services. Example: Enterprise systems with a shared service bus.", group: "Architecture, Containers & Deployment" },
  { term: "DDD", full: "Domain-Driven Design", desc: "Designing software around business domains. Example: \"Orders\" and \"Payments\" as separate bounded contexts.", lesson: 53, group: "Architecture, Containers & Deployment" },
  { term: "Strangler fig", aliases: ["strangler fig"], full: "Strangler fig", desc: "Gradually replacing a legacy system piece by piece. Example: Moving payments out of a monolith first.", lesson: 53, group: "Architecture, Containers & Deployment", once: true },
  { term: "Service discovery", aliases: ["service discovery"], full: "Service discovery", desc: "How services find each other's current addresses. Example: Calling http://payment-service instead of an IP.", lesson: 54, group: "Architecture, Containers & Deployment", once: true },
  { term: "Service mesh", aliases: ["service mesh"], full: "Service mesh", desc: "Sidecar proxies that handle traffic between services. Example: Istio or Linkerd providing mTLS, retries and metrics.", lesson: 13, group: "Architecture, Containers & Deployment", once: true },
  { term: "Sidecar", aliases: ["sidecar", "sidecars", "Sidecars"], full: "Sidecar", desc: "A helper container running next to the main one. Example: An Envoy proxy beside each service.", lesson: 54, group: "Architecture, Containers & Deployment", once: true },
  { term: "VM", full: "Virtual Machine", desc: "A full virtual computer with its own OS. Example: An EC2 instance.", lesson: 55, group: "Architecture, Containers & Deployment" },
  { term: "Container", aliases: ["container", "containers", "Containers"], full: "Container", desc: "A lightweight, isolated package of an app and its dependencies. Example: The same image runs on a laptop and in production.", lesson: 55, group: "Architecture, Containers & Deployment", once: true },
  { term: "Docker", aliases: ["docker", "dockers", "Dockers"], full: "Docker", desc: "The popular tool for building and running containers. Example: docker build, docker run.", lesson: 55, group: "Architecture, Containers & Deployment", once: true },
  { term: "Image / Registry", aliases: ["Image", "image", "images", "Images", "Registry", "registry", "registrys", "Registrys"], full: "Image / Registry", desc: "Container template / place where images are stored. Example: myshop/api:1.4.2 pushed to Docker Hub or ECR.", lesson: 55, group: "Architecture, Containers & Deployment", once: true },
  { term: "OCI", full: "Open Container Initiative", desc: "Standards for container images and runtimes. Example: Images built with Docker run on Kubernetes.", lesson: 55, group: "Architecture, Containers & Deployment" },
  { term: "K8s", full: "Kubernetes (\"K\" + 8 letters + \"s\")", desc: "Orchestrates containers across many machines. Example: Keeps 5 replicas running and restarts crashed ones.", lesson: 56, group: "Architecture, Containers & Deployment" },
  { term: "Pod", aliases: ["pod", "pods", "Pods"], full: "Pod", desc: "The smallest deployable unit in Kubernetes. Example: One app container (plus sidecars).", lesson: 56, group: "Architecture, Containers & Deployment", once: true },
  { term: "Deployment / StatefulSet / DaemonSet", aliases: ["Deployment", "deployment", "deployments", "Deployments", "StatefulSet", "DaemonSet"], full: "Deployment / StatefulSet / DaemonSet", desc: "Kubernetes workload types: stateless apps / stateful apps / one per node. Example: Deployment for an API; StatefulSet for a database.", lesson: 56, group: "Architecture, Containers & Deployment", once: true },
  { term: "Ingress", full: "Ingress", desc: "Routes external HTTP traffic into a Kubernetes cluster. Example: shop.com/api → orders service.", lesson: 56, group: "Architecture, Containers & Deployment", once: true },
  { term: "HPA", full: "Horizontal Pod Autoscaler", desc: "Adds/removes pods based on load. Example: Scale from 3 to 30 pods when CPU passes 65%.", lesson: 56, group: "Architecture, Containers & Deployment" },
  { term: "Helm", aliases: ["helm", "helms", "Helms"], full: "Helm", desc: "A package manager for Kubernetes applications. Example: Install Redis with one Helm chart.", lesson: 56, group: "Architecture, Containers & Deployment", once: true },
  { term: "CI", full: "Continuous Integration", desc: "Automatically build and test every change. Example: Every pull request runs tests.", lesson: 58, group: "Architecture, Containers & Deployment" },
  { term: "CD", full: "Continuous Delivery / Deployment", desc: "Always ready to deploy / automatically deploy. Example: Passing changes roll out to production.", lesson: 58, group: "Architecture, Containers & Deployment" },
  { term: "Blue-green deployment", aliases: ["blue-green deployment"], full: "Blue-green deployment", desc: "Two environments; switch traffic from old to new. Example: Instant rollback by switching back.", lesson: 58, group: "Architecture, Containers & Deployment", once: true },
  { term: "Canary release", aliases: ["canary release"], full: "Canary release", desc: "Send a small % of traffic to the new version first. Example: 5% → 25% → 100% if metrics look good.", lesson: 58, group: "Architecture, Containers & Deployment", once: true },
  { term: "Rolling update", aliases: ["rolling update"], full: "Rolling update", desc: "Replace instances a few at a time. Example: Kubernetes' default deploy strategy.", lesson: 58, group: "Architecture, Containers & Deployment", once: true },
  { term: "IaC", full: "Infrastructure as Code", desc: "Define infrastructure in code files. Example: Terraform creates the network, database and buckets.", lesson: 57, group: "Architecture, Containers & Deployment" },
  { term: "GitOps", full: "GitOps", desc: "Git is the source of truth; tools sync the system to it. Example: Argo CD deploys whatever is merged.", lesson: 58, group: "Architecture, Containers & Deployment" },
  { term: "DORA metrics", full: "DevOps Research and Assessment", desc: "Deployment frequency, lead time, change failure rate, time to restore. Example: Measuring delivery performance.", lesson: 58, group: "Architecture, Containers & Deployment" },
  { term: "ADR", full: "Architecture Decision Record", desc: "A short document recording a design decision. Example: \"We chose PostgreSQL because…\".", lesson: 6, group: "Architecture, Containers & Deployment" },

  // ── Cloud ─────────────────────────────────────────────────────────────
  { term: "Region", aliases: ["region", "regions", "Regions"], full: "Region", desc: "A geographic area with several data centres. Example: ap-south-1 (Mumbai).", lesson: 57, group: "Cloud", once: true },
  { term: "AZ", full: "Availability Zone", desc: "An independent data centre (or group) within a region. Example: Running servers in 3 AZs survives one data-centre failure.", lesson: 57, group: "Cloud" },
  { term: "Edge location", aliases: ["edge location"], full: "Edge location", desc: "Small sites near users for CDN and DNS. Example: Hundreds worldwide.", lesson: 57, group: "Cloud", once: true },
  { term: "IaaS", full: "Infrastructure as a Service", desc: "Rent virtual machines, disks and networks. Example: AWS EC2, Google Compute Engine.", lesson: 57, group: "Cloud" },
  { term: "PaaS", full: "Platform as a Service", desc: "Give your code; the platform runs it. Example: Heroku, Google App Engine.", lesson: 57, group: "Cloud" },
  { term: "SaaS", full: "Software as a Service", desc: "Use complete software online. Example: Gmail, Slack, Salesforce.", lesson: 57, group: "Cloud" },
  { term: "FaaS / Serverless", aliases: ["FaaS", "Serverless", "serverless"], full: "Functions as a Service", desc: "Run code on events; pay per use; no servers to manage. Example: AWS Lambda resizing images on upload.", lesson: 57, group: "Cloud", once: true },
  { term: "Cold start", aliases: ["cold start"], full: "Cold start", desc: "Extra delay when a serverless function starts fresh. Example: First request after idle takes 1 second.", lesson: 57, group: "Cloud", once: true },
  { term: "VPC", full: "Virtual Private Cloud", desc: "Your private network inside the cloud. Example: Private subnets for databases.", lesson: 57, group: "Cloud" },
  { term: "Subnet", aliases: ["subnet", "subnets", "Subnets"], full: "Subnet", desc: "A section of a network's IP range. Example: Public subnet for load balancers, private for apps.", lesson: 57, group: "Cloud", once: true },
  { term: "Security group", aliases: ["security group"], full: "Security group", desc: "A virtual firewall for cloud resources. Example: Only allow port 5432 from app servers.", lesson: 57, group: "Cloud", once: true },
  { term: "EC2 / EKS / ECS", aliases: ["EC2", "EKS", "ECS"], full: "Elastic Compute Cloud / Elastic Kubernetes Service / Elastic Container Service", desc: "AWS virtual machines / managed Kubernetes / managed containers. Example: Common AWS compute options.", lesson: 57, group: "Cloud" },
  { term: "GKE / AKS", aliases: ["GKE", "AKS"], full: "Google Kubernetes Engine / Azure Kubernetes Service", desc: "Managed Kubernetes on Google Cloud / Azure. Example: Pokémon GO ran on GKE.", lesson: 56, group: "Cloud" },
  { term: "RDS", full: "Relational Database Service", desc: "AWS managed relational databases. Example: Managed PostgreSQL with backups and failover.", lesson: 57, group: "Cloud" },
  { term: "SQS / SNS", aliases: ["SQS", "SNS"], full: "Simple Queue Service / Simple Notification Service", desc: "AWS managed queue / pub-sub. Example: SNS topic fans out to SQS queues.", lesson: 35, group: "Cloud" },
  { term: "Spot instance", aliases: ["spot instance"], full: "Spot instance", desc: "Cheap spare cloud capacity that can be taken back. Example: Up to ~90% cheaper for batch jobs.", lesson: 57, group: "Cloud", once: true },
  { term: "Shared responsibility model", aliases: ["shared responsibility model"], full: "Shared responsibility model", desc: "Provider secures the cloud; you secure what you put in it. Example: You must not make buckets public.", lesson: 57, group: "Cloud", once: true },
  { term: "FinOps", full: "Financial Operations", desc: "Managing and optimising cloud costs. Example: Tagging resources and setting budget alerts.", lesson: 57, group: "Cloud" },
  { term: "Multi-cloud / Hybrid cloud", aliases: ["Multi-cloud", "multi-cloud", "multi-clouds", "Multi-clouds", "Hybrid cloud", "hybrid cloud"], full: "Multi-cloud / Hybrid cloud", desc: "Using several providers / mixing cloud and your own data centre. Example: Some workloads on AWS, some on-premises.", lesson: 57, group: "Cloud", once: true },
];

